import glob,os
from docx import Document
def dump(p):
    d=Document(p); out=[]
    body=d.element.body
    from docx.table import Table
    from docx.text.paragraph import Paragraph
    for child in body.iterchildren():
        if child.tag.endswith('}p'):
            out.append(Paragraph(child,d).text)
        elif child.tag.endswith('}tbl'):
            t=Table(child,d)
            for r in t.rows:
                out.append(' | '.join(c.text for c in r.cells))
    open('/tmp/x/'+os.path.basename(p)+'.txt','w').write('\n'.join(out))
for p in glob.glob('specs/*.docx')+glob.glob('site/*.docx')+glob.glob('correspondence/*.docx'):
    dump(p)
EOF
